import re, json
with open('/tmp/issues.html', 'r', encoding='utf-8') as f:
    text = f.read()

# Find all scripts
scripts = re.findall(r'<script[^>]*>(.*?)</script>', text, re.DOTALL)
for i, s in enumerate(scripts):
    if 'repository' in s or 'issueCount' in s or 'open_issues' in s or 'issues' in s:
        try:
            data = json.loads(s)
            if isinstance(data, dict):
                print(f'Script {i} keys: {list(data.keys())}')
                if 'payload' in data and 'repository' in data['payload']:
                    repo = data['payload']['repository']
                    if 'issues' in repo:
                        print('Issues:', repo['issues'])
                    if 'openIssues' in repo:
                        print('openIssues:', repo['openIssues'])
                    if 'issueCount' in repo:
                        print('issueCount:', repo['issueCount'])
        except Exception as e:
            pass

# Also look for text counts
m = re.search(r'Open[^0-9]*([0-9]+)[^0-9]*issue', text)
print('Regex open issues:', m.group(1) if m else 'None')

# look for data-testid='open-issue-count'
m2 = re.search(r'data-testid=\"open-issue-count\"[^>]*>([^<]+)</span>', text)
print('data-testid open:', m2.group(1) if m2 else 'None')
"

